import logging
from concurrent.futures import ThreadPoolExecutor
from datetime import datetime, timezone

from backend.app.config import GEMINI_MODEL
from backend.app.schemas import AnomalyRequest, PortfolioRequest
from backend.app.services.report import verify
from backend.app.services.report.facts import build_facts
from backend.app.services.report.prompt import ReportDraft

logger = logging.getLogger(__name__)

ANOMALY_DAYS = 365
MAX_ATTEMPTS = 2

DISCLAIMER = (
    "This report was generated by AI (Google Gemini) from the output of statistical models. "
    "It is for information only and is not financial, investment, legal or tax advice. "
    "Model estimates can be wrong and past data does not predict future results. "
    "Do not base investment decisions on this report alone."
)


class ReportError(Exception):
    pass


def render_markdown(draft: ReportDraft) -> str:
    bullets = "\n".join(f"- {r}" for r in draft.recommendations)
    return (
        f"# {draft.title}\n\n"
        f"## Risk outlook\n{draft.risk_outlook}\n\n"
        f"## Unusual market activity\n{draft.unusual_activity}\n\n"
        f"## News sentiment\n{draft.news_sentiment}\n\n"
        f"## Summary and recommendations\n{draft.summary}\n\n{bullets}\n\n"
        f"---\n*{DISCLAIMER}*\n"
    )


def sections(draft: ReportDraft) -> list[dict]:
    return [
        {"heading": "Risk outlook", "body": draft.risk_outlook},
        {"heading": "Unusual market activity", "body": draft.unusual_activity},
        {"heading": "News sentiment", "body": draft.news_sentiment},
        {"heading": "Summary and recommendations", "body": draft.summary, "bullets": draft.recommendations},
    ]


class ReportService:
    def __init__(self, risk_fn, anomaly_fn, sentiment_fn, writer):
        self.risk_fn = risk_fn
        self.anomaly_fn = anomaly_fn
        self.sentiment_fn = sentiment_fn
        self.writer = writer

    def _gather(self, request: PortfolioRequest):
        tickers = [a.ticker for a in request.portfolio]
        anomaly_request = AnomalyRequest(portfolio=request.portfolio, days=ANOMALY_DAYS)
        reasons = {}

        def optional(name, fn, *args):
            try:
                return fn(*args)
            except Exception as e:
                logger.warning("report: %s unavailable: %s", name, e)
                reasons[name] = str(e) if isinstance(e, ValueError) else "temporarily unavailable"
                return None

        with ThreadPoolExecutor(max_workers=3) as pool:
            risk = pool.submit(self.risk_fn, request)
            anomalies = pool.submit(optional, "anomalies", self.anomaly_fn, anomaly_request)
            sentiment = pool.submit(optional, "sentiment", self.sentiment_fn, tickers)
            return risk.result(), anomalies.result(), sentiment.result(), reasons

    def _write(self, facts: dict):
        problems, issues = None, []

        for attempt in range(1, MAX_ATTEMPTS + 1):
            try:
                draft = self.writer.write(facts, problems)
            except Exception as e:
                logger.exception("report: writer failed")
                raise ReportError(f"the AI writer failed ({type(e).__name__})")

            problems = verify.check(draft, facts)
            if not problems:
                return draft, attempt, issues

            issues.extend(problems)
            logger.warning("report: draft rejected (attempt %s): %s", attempt, problems)

        raise ReportError("the AI draft did not pass the number check")

    def generate(self, request: PortfolioRequest) -> dict:
        risk, anomalies, sentiment, reasons = self._gather(request)
        facts = build_facts(risk, anomalies, sentiment, reasons)
        draft, attempts, issues = self._write(facts)

        return {
            "report": {"title": draft.title, "sections": sections(draft)},
            "markdown": render_markdown(draft),
            "disclaimer": DISCLAIMER,
            "meta": {
                "model": GEMINI_MODEL,
                "attempts": attempts,
                "rejected_draft_issues": issues,
                "generated_at": datetime.now(timezone.utc).isoformat(),
            },
            "facts": facts,
        }
